mapper.update:
UPDATE admin_case c JOIN admin_case_relation l ON l.admin_case_id=c.id AND l.is_primary=1
    SET c.case_status='closed',c.active_case_key=NULL,c.closed_at=#{at},c.closed_by_admin_user_id=#{actor},c.version=c.version+1,c.updated_at=#{at}
    WHERE l.relation_type='order_issue_report' AND l.relation_id=#{issue} AND c.case_status NOT IN ('closed','cancelled')

UPDATE platform_intervention_record i JOIN admin_case_relation s ON s.relation_id=i.id AND s.relation_type='admin_intervention' AND s.relation_role='source' AND s.is_primary=0
    JOIN admin_case_relation r ON r.admin_case_id=s.admin_case_id AND r.relation_type='arbitration_case' AND r.relation_id=#{id}
    SET i.intervention_status='resolved',i.resolved_at=#{at},i.updated_at=#{at} WHERE i.rental_order_id=#{order} AND i.intervention_status IN ('open','processing')
